import{_ as l,o as e,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-01-11","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-01-11","date":"2022-01-11T00:00:00.000Z","updated":"2022-01-12T00:00:00.000Z","tags":["Ceph","Orchestrator","Quincy 版本","Rook","回归问题"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-01-11.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-01-11.md","lastUpdated":1780459816000}'),r={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-01-11.md"};function o(n,a,s,u,c,h){return e(),i("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-orchestrator-会议" tabindex="-1">会议主题：Orchestrator 会议 <a class="header-anchor" href="#会议主题-orchestrator-会议" aria-label="Permalink to &quot;会议主题：Orchestrator 会议&quot;">​</a></h4><h4 id="日期-2022年1月11日" tabindex="-1">日期：2022年1月11日 <a class="header-anchor" href="#日期-2022年1月11日" aria-label="Permalink to &quot;日期：2022年1月11日&quot;">​</a></h4><h4 id="参会人员-具体人员名单" tabindex="-1">参会人员：[具体人员名单] <a class="header-anchor" href="#参会人员-具体人员名单" aria-label="Permalink to &quot;参会人员：[具体人员名单]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>Quincy 版本特性冻结</strong></p><ul><li>讨论了 Quincy 版本的特性冻结时间，原计划是在本周结束，但具体时间取决于 RBG 和 FFS 等组件的完成情况。</li><li>强调了 self-adm 二进制文件的重构需要在 Quincy 发布前完成。</li></ul></li><li><p><strong>Quincy 版本的待办事项</strong></p><ul><li>讨论了 agent 和特定的 pull request 是否需要合并以满足特性冻结。</li><li>强调了文件权限和主机缓存大小问题的重要性。</li></ul></li><li><p><strong>Rook Manager Module 的测试和使用</strong></p><ul><li>讨论了 Rook Manager Module 在 Quincy 版本中的测试情况，目前仅在 CI 中测试。</li><li>该模块对于 multi-site 配置非常重要，但不会包含在 Quincy 的初始版本中。</li></ul></li><li><p><strong>Quincy 版本的后续行动计划</strong></p><ul><li>确认了所有新特性都可以在未来的版本中轻松回溯。</li><li>讨论了不同 Rook 版本的兼容性问题，确认 Rook 的接口是向后兼容的。</li></ul></li><li><p><strong>ISCSI 的回归问题</strong></p><ul><li>讨论了 ISCSI 的回归问题，目前尚未解决，需要进一步调查。</li></ul></li><li><p><strong>Backporting 问题</strong></p><ul><li>讨论了 backporting 的复杂性，特别是由于 Pacific 和 Quincy 版本之间的差异。</li><li>确认了一些具体的 pull request 需要进行 backporting，并讨论了分配任务的可能性。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认了 Quincy 版本的特性冻结时间将取决于其他组件的完成情况。</li><li>确认了 self-adm 二进制文件的重构需要在 Quincy 发布前完成。</li><li>确认了 Rook Manager Module 的重要性，但不会包含在 Quincy 的初始版本中。</li><li>确认了 ISCSI 的回归问题需要进一步调查。</li><li>确认了 backporting 的复杂性，并讨论了分配任务的可能性。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续监控其他组件的进度，以确定 Quincy 版本的特性冻结时间。</li><li>完成 self-adm 二进制文件的重构工作。</li><li>继续测试和验证 Rook Manager Module 的功能。</li><li>调查并解决 ISCSI 的回归问题。</li><li>分配并完成 backporting 任务。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在确认无其他议题后结束，感谢所有参会人员，并约定下周再次开会。</li></ul>',12)])])}const _=l(r,[["render",o]]);export{p as __pageData,_ as default};
